--
-- TOC entry 578 (class 1255 OID 17875)
-- Name: _bcast_cols_for_status(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public._bcast_cols_for_status(s text) RETURNS text[]
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
BEGIN
  -- 'pending' contributes to nothing.
  IF s = 'pending' THEN RETURN ARRAY[]::TEXT[]; END IF;
  IF s = 'sent'      THEN RETURN ARRAY['sent_count']; END IF;
  IF s = 'delivered' THEN RETURN ARRAY['sent_count','delivered_count']; END IF;
  IF s = 'read'      THEN RETURN ARRAY['sent_count','delivered_count','read_count']; END IF;
  IF s = 'replied'   THEN RETURN ARRAY['sent_count','delivered_count','read_count','replied_count']; END IF;
  IF s = 'failed'    THEN RETURN ARRAY['failed_count']; END IF;
  RETURN ARRAY[]::TEXT[];
END;
$$;


ALTER FUNCTION public._bcast_cols_for_status(s text) OWNER TO postgres;

--
-- TOC entry 720 (class 1255 OID 19846)
-- Name: accounts_set_trial_defaults(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.accounts_set_trial_defaults() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_trial_days INTEGER;
BEGIN
  -- An account that arrives already provisioned never needs to choose.
  IF NEW.subscription_ends_at IS NOT NULL
     OR NEW.subscription_plan_id IS NOT NULL
     OR NEW.subscription_status = 'none' THEN
    NEW.plan_selection_required := FALSE;
  END IF;

  -- Respect an explicit window when the caller already supplied one
  -- (super-admin tooling creating a pre-paid account).
  IF NEW.trial_ends_at IS NOT NULL THEN
    NEW.plan_selection_required := FALSE;
    RETURN NEW;
  END IF;

  SELECT trial_days INTO v_trial_days FROM subscription_settings LIMIT 1;
  v_trial_days := COALESCE(v_trial_days, 14);

  NEW.trial_started_at := COALESCE(NEW.trial_started_at, NOW());
  NEW.trial_ends_at := NEW.trial_started_at + (v_trial_days || ' days')::INTERVAL;

  IF NEW.subscription_status IS NULL OR NEW.subscription_status = 'trialing' THEN
    NEW.subscription_status := 'trialing';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.accounts_set_trial_defaults() OWNER TO postgres;

--
-- TOC entry 731 (class 1255 OID 21005)
-- Name: bootstrap_user_account(uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.bootstrap_user_account(p_user_id uuid, p_email text, p_full_name text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_account_id UUID;
BEGIN
  IF EXISTS (SELECT 1 FROM public.profiles WHERE user_id = p_user_id) THEN
    RETURN;
  END IF;

  VALUES (COALESCE(NULLIF(p_full_name, ''), p_email, 'My account'), p_user_id)
  RETURNING id INTO v_account_id;

  VALUES (p_user_id, COALESCE(p_full_name, ''), p_email, v_account_id, 'owner');
END;
$$;


