--
-- TOC entry 727 (class 1255 OID 20740)
-- Name: fn_apply_message_status(text, text, timestamp with time zone, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_apply_message_status(p_message_id text, p_status text, p_ts timestamp with time zone, p_error_code text DEFAULT NULL::text, p_error_message text DEFAULT NULL::text, p_error_details jsonb DEFAULT NULL::jsonb) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_rows INTEGER;
BEGIN
  UPDATE messages m
  SET
    status = CASE
               WHEN p_status = 'failed'
                 THEN 'failed'
               WHEN message_status_rank(p_status) > message_status_rank(m.status)
                 THEN p_status
               ELSE m.status
             END,
    sent_at = CASE
                WHEN p_status = 'sent' THEN COALESCE(m.sent_at, p_ts)
                ELSE m.sent_at
              END,
    delivered_at = CASE
                     WHEN p_status = 'delivered' THEN COALESCE(m.delivered_at, p_ts)
                     ELSE m.delivered_at
                   END,
    read_at = CASE
                WHEN p_status = 'read' THEN COALESCE(m.read_at, p_ts)
                ELSE m.read_at
              END,
    error_code    = CASE WHEN p_status = 'failed' THEN COALESCE(p_error_code, m.error_code)       ELSE NULL END,
    error_message = CASE WHEN p_status = 'failed' THEN COALESCE(p_error_message, m.error_message) ELSE NULL END,
    error_details = CASE WHEN p_status = 'failed' THEN COALESCE(p_error_details, m.error_details) ELSE NULL END
  WHERE m.message_id = p_message_id;

  GET DIAGNOSTICS v_rows = ROW_COUNT;
  RETURN v_rows;
END;
$$;


ALTER FUNCTION public.fn_apply_message_status(p_message_id text, p_status text, p_ts timestamp with time zone, p_error_code text, p_error_message text, p_error_details jsonb) OWNER TO postgres;

