--
-- TOC entry 742 (class 1255 OID 21328)
-- Name: fn_sa_list_notifications_for_admin(uuid, text, text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_sa_list_notifications_for_admin(p_user_id uuid, p_read_filter text DEFAULT 'all'::text, p_type text DEFAULT NULL::text, p_search text DEFAULT NULL::text, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0) RETURNS TABLE(id uuid, type text, severity text, title text, body text, account_id uuid, account_name text, entity_type text, entity_id uuid, link text, created_at timestamp with time zone, is_read boolean, total_count bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH scoped AS (
    SELECT
      n.*,
      EXISTS (
        SELECT 1
        FROM super_admin_notification_reads r
        WHERE r.notification_id = n.id
          AND r.user_id = p_user_id
      ) AS operator_has_read
    FROM super_admin_notifications n
    WHERE EXISTS (
      SELECT 1
      FROM profiles p
      WHERE p.user_id = p_user_id
        AND p.is_super_admin = TRUE
    )
      AND (p_type IS NULL OR n.type = p_type)
      AND (
        NULLIF(BTRIM(p_search), '') IS NULL
        OR n.title ILIKE '%' || BTRIM(p_search) || '%'
        OR COALESCE(n.body, '') ILIKE '%' || BTRIM(p_search) || '%'
        OR COALESCE(n.account_name, '') ILIKE '%' || BTRIM(p_search) || '%'
      )
  ), filtered AS (
    SELECT *
    FROM scoped
    WHERE p_read_filter = 'all'
      OR (p_read_filter = 'read' AND operator_has_read)
      OR (p_read_filter = 'unread' AND NOT operator_has_read)
  )
  SELECT
    f.id,
    f.type,
    f.severity,
    f.title,
    f.body,
    f.account_id,
    f.account_name,
    f.entity_type,
    f.entity_id,
    f.link,
    f.created_at,
    f.operator_has_read AS is_read,
    COUNT(*) OVER () AS total_count
  FROM filtered f
  ORDER BY f.created_at DESC, f.id DESC
  LIMIT LEAST(GREATEST(p_limit, 1), 100)
  OFFSET GREATEST(p_offset, 0);
$$;


ALTER FUNCTION public.fn_sa_list_notifications_for_admin(p_user_id uuid, p_read_filter text, p_type text, p_search text, p_limit integer, p_offset integer) OWNER TO postgres;

--
-- TOC entry 741 (class 1255 OID 21323)
-- Name: fn_sa_mark_all_notifications_read(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_sa_mark_all_notifications_read() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_count INTEGER;
BEGIN
  IF NOT public.is_super_admin_user() THEN
    RETURN 0;
  END IF;

  WITH inserted AS (
    SELECT n.id, auth.uid()
    FROM super_admin_notifications n
    WHERE NOT EXISTS (
      SELECT 1 FROM super_admin_notification_reads r
      WHERE r.notification_id = n.id AND r.user_id = auth.uid()
    )
    ON CONFLICT (notification_id, user_id) DO NOTHING
    RETURNING 1
  )
  SELECT COUNT(*)::INTEGER INTO v_count FROM inserted;

  RETURN v_count;
END;
$$;


ALTER FUNCTION public.fn_sa_mark_all_notifications_read() OWNER TO postgres;

--
-- TOC entry 743 (class 1255 OID 21329)
-- Name: fn_sa_notification_summary_for_admin(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_sa_notification_summary_for_admin(p_user_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH authorized AS (
    SELECT EXISTS (
      SELECT 1 FROM profiles p
      WHERE p.user_id = p_user_id
        AND p.is_super_admin = TRUE
    ) AS allowed
  ), notification_stats AS (
    SELECT
      COUNT(*)::INTEGER AS total,
      COUNT(*) FILTER (
        WHERE NOT EXISTS (
          SELECT 1
          FROM super_admin_notification_reads r
          WHERE r.notification_id = n.id
            AND r.user_id = p_user_id
        )
      )::INTEGER AS unread,
      COUNT(*) FILTER (WHERE n.severity = 'critical')::INTEGER AS critical,
      COUNT(*) FILTER (
        WHERE n.created_at >= NOW() - INTERVAL '24 hours'
      )::INTEGER AS recent_24_hours
    FROM super_admin_notifications n, authorized a
    WHERE a.allowed
  ), type_stats AS (
    SELECT COALESCE(JSONB_OBJECT_AGG(grouped.type, grouped.count), '{}'::JSONB) AS by_type
    FROM (
      SELECT n.type, COUNT(*)::INTEGER AS count
      FROM super_admin_notifications n, authorized a
      WHERE a.allowed
      GROUP BY n.type
    ) grouped
  )
  SELECT JSONB_BUILD_OBJECT(
    'total', s.total,
    'unread', s.unread,
    'critical', s.critical,
    'recent_24_hours', s.recent_24_hours,
    'by_type', t.by_type
  )
  FROM notification_stats s
  CROSS JOIN type_stats t;
$$;


ALTER FUNCTION public.fn_sa_notification_summary_for_admin(p_user_id uuid) OWNER TO postgres;

